sql.order_economics:
{{ config(materialized='incremental',unique_key='order_id',incremental_strategy='delete+insert') }}
-- Aggregate each child independently; joining line items to payments directly multiplies money.
with lines as (select order_id,sum(gross)::bigint as gross,sum(discount)::bigint as discount,
 sum(cogs)::bigint as cogs,sum(refunded)::bigint as refunded,sum(net_revenue)::bigint as net_revenue
 from {{ ref('line_economics') }} group by order_id),
 fees as (select order_id,sum(fee)::bigint as fees from {{ source('raw','payments') }} where status='succeeded' group by order_id)
select o.order_id,o.customer_id,o.ordered_at,o.channel,l.gross,l.discount,l.cogs,o.shipping,
 coalesce(f.fees,0)::bigint as fees,l.refunded,l.net_revenue,
 (l.net_revenue-l.cogs-o.shipping-coalesce(f.fees,0))::bigint as contribution_before_ads
from {{ source('raw','orders') }} o join lines l using(order_id) left join fees f using(order_id)
{% if is_incremental() %}where o.order_id in ({{ changed_orders() }}){% endif %}

sql.channel_acquisition:
-- First observed order; deterministic same-day tie break by order_id.
with ranked as (
 select *,row_number() over(partition by customer_id order by ordered_at,order_id) as rn from {{ source('raw','orders') }}
), acquired as (
 select channel,count(*) as first_customers from ranked where rn=1 group by channel
), economics as (
 select channel,sum(ad_spend)::bigint as ad_spend,sum(net_revenue)::bigint as net_revenue
 from {{ ref('monthly') }} group by channel
)
select e.*,coalesce(a.first_customers,0)::bigint as first_customers,
 e.ad_spend*1.0/nullif(a.first_customers,0) as first_order_cac_paise,
 e.net_revenue*1.0/nullif(e.ad_spend,0) as blended_revenue_to_spend
from economics e left join acquired a using(channel)

sql.line_economics:
{{ config(materialized='incremental',unique_key='line_id',incremental_strategy='delete+insert') }}
with refunds as (select line_id,sum(amount)::bigint as refunded from {{ source('raw','refunds') }} group by line_id)
select l.line_id,l.order_id,o.customer_id,o.ordered_at,o.channel,l.product,l.quantity,
 (l.quantity*l.unit_price)::bigint as gross,l.discount,(l.quantity*l.unit_cost)::bigint as cogs,
 coalesce(r.refunded,0)::bigint as refunded,
 (l.quantity*l.unit_price-l.discount-coalesce(r.refunded,0))::bigint as net_revenue,
 (l.quantity*(l.unit_price-l.unit_cost)-l.discount-coalesce(r.refunded,0))::bigint as merchandise_contribution
from {{ source('raw','line_items') }} l join {{ source('raw','orders') }} o using(order_id)
left join refunds r using(line_id)
{% if is_incremental() %}where l.order_id in ({{ changed_orders() }}){% endif %}

sql.monthly:
{{ config(materialized='incremental',unique_key=['month','channel'],incremental_strategy='delete+insert') }}
-- Revenue follows order date; refund grants and actual payment fees follow their event dates.
with ledger as (
 select date_trunc('month',ordered_at)::date as month,channel,gross,discount,0::bigint as refunds,cogs,shipping,0::bigint as fees,0::bigint as ad_spend,1 as orders from {{ ref('order_economics') }}
 union all select date_trunc('month',r.refunded_at)::date,o.channel,0,0,r.amount,0,0,0,0,0
 from {{ source('raw','refunds') }} r join {{ source('raw','line_items') }} l using(line_id) join {{ source('raw','orders') }} o using(order_id)
 union all select date_trunc('month',p.occurred_at)::date,o.channel,0,0,0,0,0,p.fee,0,0 from {{ source('raw','payments') }} p join {{ source('raw','orders') }} o using(order_id) where p.status='succeeded'
 union all select date_trunc('month',spent_at)::date,channel,0,0,0,0,0,0,amount,0 from {{ source('raw','spend') }}
), affected as (
 select date_trunc('month',ordered_at)::date as month,channel from {{ source('raw','orders') }} where order_id in ({{ changed_orders() }})
 union select date_trunc('month',r.refunded_at)::date,o.channel from {{ source('raw','refunds') }} r join {{ source('raw','line_items') }} l using(line_id) join {{ source('raw','orders') }} o using(order_id) where r._batch_id>{{ var('lower_batch',0) }}
 union select date_trunc('month',p.occurred_at)::date,o.channel from {{ source('raw','payments') }} p join {{ source('raw','orders') }} o using(order_id) where p._batch_id>{{ var('lower_batch',0) }}
 union select date_trunc('month',spent_at)::date,channel from {{ source('raw','spend') }} where _batch_id>{{ var('lower_batch',0) }}
)
select month,channel,sum(orders)::bigint as orders,sum(gross)::bigint as gross,sum(discount)::bigint as discount,
 sum(refunds)::bigint as refunds,sum(cogs)::bigint as cogs,sum(shipping)::bigint as shipping,sum(fees)::bigint as fees,
 sum(ad_spend)::bigint as ad_spend,sum(gross-discount-refunds)::bigint as net_revenue,
 sum(gross-discount-refunds-cogs-shipping-fees-ad_spend)::bigint as contribution
from ledger
{% if is_incremental() %}where (month,channel) in (select month,channel from affected){% endif %}
group by all

sql.sku_returns:
{{ config(materialized='incremental',unique_key=['channel','product'],incremental_strategy='delete+insert') }}
select channel,product,count(distinct order_id)::bigint as orders,sum(quantity)::bigint as units,
 count(distinct order_id) filter(where refunded>0)::bigint as refunded_orders,
 sum(refunded)::bigint as refund_amount,sum(gross-discount)::bigint as charged_revenue,
 sum(net_revenue)::bigint as net_revenue,sum(merchandise_contribution)::bigint as merchandise_contribution,
 count(distinct order_id) filter(where refunded>0)*1.0/count(distinct order_id) as refunded_order_rate,
 sum(refunded)*1.0/nullif(sum(gross-discount),0) as refund_value_rate
from {{ ref('line_economics') }}
{% if is_incremental() %}where (channel,product) in (select channel,product from {{ ref('line_economics') }} where order_id in ({{ changed_orders() }})){% endif %}
group by all
